// Regenerates src/lib/fixtures/snapshot.ts from the backend's canonical fixture,
// so `tsc` type-checks the same snapshot that pytest validates.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const source = resolve(here, "../../backend/tests/fixtures/snapshot.json");
const target = resolve(here, "../src/lib/fixtures/snapshot.ts");

const data = JSON.parse(readFileSync(source, "utf8"));
const header =
  "// GENERATED by `npm run sync:fixture` from backend/tests/fixtures/snapshot.json.\n" +
  "// Do not edit by hand.\n" +
  'import type { SessionSnapshot } from "../types";\n\n';

writeFileSync(
  target,
  `${header}export const snapshotFixture: SessionSnapshot = ${JSON.stringify(data, null, 2)};\n`,
);
console.log(`Wrote ${target}`);
